<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Http\Requests\ConfigurationRequest;use App\Http\Resources\ConfigurationResource;use App\Models\Configuration;use App\Services\ConfigurationService;use Illuminate\Support\Facades\{Gate,DB};
class ConfigurationController extends Controller {public function __construct(private ConfigurationService $service){}public function index(){return ConfigurationResource::collection(Configuration::where('user_id',auth()->id())->with('items.component')->latest()->paginate(10));}public function show(Configuration $configuration){Gate::authorize('view',$configuration);return new ConfigurationResource($configuration->load('items.component'));}public function store(ConfigurationRequest $r){return DB::transaction(function()use($r){$c=$r->user()->configurations()->create(['name'=>$r->validated('name')]);if($r->has('items'))$c=$this->service->save($c,$r->validated('items'));return (new ConfigurationResource($c->load('items.component')))->response()->setStatusCode(201);});}public function update(ConfigurationRequest $r,Configuration $configuration){Gate::authorize('update',$configuration);$configuration->update(['name'=>$r->validated('name')]);if($r->has('items'))$configuration=$this->service->save($configuration,$r->validated('items'));return new ConfigurationResource($configuration->load('items.component'));}public function destroy(Configuration $configuration){Gate::authorize('delete',$configuration);$configuration->delete();return response()->noContent();}}
